import {poseHelpLabels} from './pose-help.mjs';
import {createStudioPlannerStore,normalizeStudioPlan,studioPlanText,studioPlannerKey,studioAim} from './studio-planner.mjs';
import {attachPoseStudio,poseLabels} from './studio-poses-ui.mjs';

const poseWorkspaceWords={
 sync:'Changes are saved automatically and shared with the main Studio tab. Closing this tab keeps your saved scene.|A módosítások automatikusan mentődnek, és a Studio főlapján is megjelennek. A lap bezárása után a mentett jelenet megmarad.|Änderungen werden automatisch gespeichert und mit dem Studio-Haupttab geteilt. Der gespeicherte Plan bleibt nach dem Schließen erhalten.|Les modifications sont enregistrées automatiquement et partagées avec l’onglet principal. Fermer cet onglet conserve la scène.|Los cambios se guardan automáticamente y se comparten con Studio. Cerrar esta pestaña conserva la escena guardada.|Le modifiche vengono salvate automaticamente e condivise con Studio. Chiudere la scheda mantiene la scena salvata.|As alterações são guardadas automaticamente e partilhadas com o Studio. Fechar o separador mantém a cena guardada.|Zmiany są zapisywane automatycznie i współdzielone z główną kartą Studio. Zamknięcie karty zachowuje zapisaną scenę.',
 copy:'Copy studio directions|Stúdióleírás másolása|Studiobeschreibung kopieren|Copier les instructions|Copiar instrucciones|Copia istruzioni studio|Copiar instruções|Kopiuj wskazówki studia',
 close:'Close this tab|Lap bezárása|Diesen Tab schließen|Fermer cet onglet|Cerrar pestaña|Chiudi scheda|Fechar separador|Zamknij kartę',
 output:'Studio directions (editable)|Stúdióleírás (szerkeszthető)|Studiobeschreibung (bearbeitbar)|Instructions (modifiables)|Instrucciones (editables)|Istruzioni (modificabili)|Instruções (editáveis)|Wskazówki (edytowalne)',
 rebuild:'Rebuild directions from plan|Leírás újraépítése a tervből|Beschreibung aus Plan erneuern|Recréer depuis le plan|Reconstruir desde el plan|Ricrea dal piano|Recriar a partir do plano|Odbuduj opis z planu',
 saved:'Saved.|Mentve.|Gespeichert.|Enregistré.|Guardado.|Salvato.|Guardado.|Zapisano.',copied:'Copied.|Másolva.|Kopiert.|Copié.|Copiado.|Copiato.|Copiado.|Skopiowano.',
 changed:'The scene changed in another tab. The latest saved scene is now shown; please repeat your last edit.|A jelenet egy másik lapon megváltozott. Most a legutóbbi mentést látod; ismételd meg az utolsó módosítást.|Die Szene wurde in einem anderen Tab geändert. Der neueste Stand wird angezeigt; letzte Änderung bitte wiederholen.|La scène a changé dans un autre onglet. La dernière sauvegarde est affichée ; répétez votre modification.|La escena cambió en otra pestaña. Se muestra la última versión; repite el último cambio.|La scena è cambiata in un’altra scheda. È mostrata l’ultima versione; ripeti l’ultima modifica.|A cena mudou noutro separador. A última versão está visível; repita a última alteração.|Scena zmieniła się w innej karcie. Wyświetlono najnowszy zapis; powtórz ostatnią zmianę.',
 failed:'Could not save. The previous saved scene is preserved. Use the normal Studio launcher if local storage is unavailable.|A mentés nem sikerült. A korábbi mentett jelenet megmaradt. Ha a helyi tároló nem érhető el, a megszokott indítóval nyisd a Studiót.|Speichern fehlgeschlagen. Die vorige Szene bleibt erhalten. Bei fehlendem Speicher Studio normal starten.|Échec de sauvegarde. La scène précédente est conservée. Si le stockage est indisponible, utilisez le lanceur habituel.|No se pudo guardar. Se conserva la escena anterior. Si no hay almacenamiento local, usa el iniciador normal.|Salvataggio non riuscito. La scena precedente è conservata. Se manca l’archivio locale, avvia Studio normalmente.|Não foi possível guardar. Cena anterior preservada. Se o armazenamento estiver indisponível, inicie o Studio normalmente.|Nie udało się zapisać. Poprzednia scena zachowana. Jeśli pamięć lokalna jest niedostępna, uruchom Studio zwykłym sposobem.',
 cameraHeight:'Camera height (m)|Kameramagasság (m)|Kamerahöhe (m)|Hauteur caméra (m)|Altura cámara (m)|Altezza camera (m)|Altura da câmara (m)|Wysokość kamery (m)',lens:'Lens (mm)|Objektív (mm)|Objektiv (mm)|Focale (mm)|Objetivo (mm)|Obiettivo (mm)|Objetiva (mm)|Obiektyw (mm)',
 aim:'Aim at studio target|Irányítás a stúdió célpontjára|Auf Studioziel richten|Viser la cible du studio|Apuntar al objetivo del estudio|Punta al bersaglio dello studio|Apontar ao alvo do estúdio|Celuj w punkt studia',
 yaw:'Camera yaw (°)|Kamera elfordulása (°)|Kameraschwenk (°)|Rotation caméra (°)|Giro cámara (°)|Rotazione camera (°)|Rotação da câmara (°)|Obrót kamery (°)',pitch:'Camera pitch (°)|Kamera billenése (°)|Kameraneigung (°)|Inclinaison caméra (°)|Inclinación cámara (°)|Inclinazione camera (°)|Inclinação da câmara (°)|Pochylenie kamery (°)',roll:'Camera roll (°)|Kamera dőlése (°)|Kamerarollwinkel (°)|Roulis caméra (°)|Balanceo cámara (°)|Rollio camera (°)|Inclinação lateral (°)|Przechył kamery (°)',ratio:'Aspect ratio|Képarány|Seitenverhältnis|Format|Proporción|Proporzioni|Proporção|Proporcje',
 backup:'Save full scene JSON|Teljes jelenet JSON mentése|Ganze Szene als JSON speichern|Enregistrer toute la scène JSON|Guardar escena completa JSON|Salva scena completa JSON|Guardar cena completa JSON|Zapisz całą scenę JSON'
};
export function poseWorkspaceLabels(code='EN'){const i=Math.max(0,['EN','HU','DE','FR','ES','IT','PT','PL'].indexOf(code));return {...poseLabels(code),...Object.fromEntries(Object.entries(poseWorkspaceWords).map(([k,v])=>[k,v.split('|')[i]]))};}

export function mountPoseWorkspace(initialPlan,initialLanguage='EN',initialReference=null){
 const clone=v=>JSON.parse(JSON.stringify(v));let language=['EN','HU','DE','FR','ES','IT','PT','PL'].includes(initialLanguage)?initialLanguage:'EN',store,saved,state=normalizeStudioPlan(initialPlan),locked=false,ui=null;
 const t=()=>poseWorkspaceLabels(language),el=(tag,cls='')=>{const n=document.createElement(tag);if(cls)n.className=cls;return n;},texts=[];
 const word=(tag,key)=>{const n=el(tag);texts.push([n,key]);return n;};
 document.body.className='pose-workspace vs-content';const header=el('header','pose-workspace-header'),heading=word('h1','title'),lang=el('select');lang.setAttribute('aria-label','Language');lang.dataset.poseWorkspace='language';for(const code of ['EN','HU','DE','FR','ES','IT','PT','PL'])lang.append(new Option(code,code));lang.value=language;
 const status=el('p','pose-workspace-status');status.setAttribute('role','status');
 const output=el('textarea');output.rows=7;output.maxLength=10000;output.dataset.poseWorkspace='output';
 const button=(key,handler)=>{const b=word('button',key);b.type='button';b.dataset.poseWorkspace=key;b.addEventListener('click',handler);return b;};
 const copy=button('copy',async()=>{try{await navigator.clipboard.writeText(output.value);status.textContent=t().copied;}catch{status.textContent=t().failed;}}),close=button('close',()=>window.close());header.append(heading,lang,copy,close);document.body.append(header,word('p','sync'),status);
 try{store=createStudioPlannerStore(localStorage);locked=store.problem();saved=store.read();if(localStorage.getItem(studioPlannerKey))state=saved.state;}catch{locked=true;}
 const host=el('main');document.body.append(host);
 function syncExternal(){try{const fresh=createStudioPlannerStore(localStorage);if(fresh.problem())throw Error('storage');ui?.cancelDrag();store=fresh;saved=store.read();state=saved.state;locked=false;refresh();return true;}catch{locked=true;status.textContent=t().failed;refresh();return false;}}
 function commit(next){if(locked||!store){status.textContent=t().failed;return false;}try{saved=store.save({...saved,state:normalizeStudioPlan(next)});state=saved.state;status.textContent=t().saved;refresh();return true;}catch(error){if(error?.message==='conflict'){syncExternal();status.textContent=t().changed;}else status.textContent=t().failed;return false;}}
 ui=attachPoseStudio({host,getPlan:()=>clone(state),onCommit:commit,getLanguage:()=>language,isLocked:()=>locked});ui.open();const referenceReady=initialReference?ui.restoreReference(initialReference):Promise.resolve(false);
 const camera=el('details','pose-workspace-camera');camera.append(word('summary','camera'));const cameraFields=el('div','pose-controls'),cameraInputs={};camera.append(cameraFields);host.querySelector('.pose-controls').append(camera);
 const spec=[['x','number',-5,5,.01],['cameraHeight','number',.1,6,.01],['z','number',-5,5,.01],['lens','number',14,200,1],['aim','checkbox'],['yaw','number',-180,180,.1],['pitch','number',-85,85,.1],['roll','number',-45,45,.1],['ratio','select']];
 for(const [key,type,min,max,step]of spec){const label=el('label'),n=el(type==='select'?'select':'input');if(type!=='select')n.type=type;if(min!==undefined){n.min=min;n.max=max;n.step=step;}if(key==='ratio')for(const ratio of ['3:2','16:9','9:16','1:1','4:3'])n.append(new Option(ratio,ratio));n.dataset.poseCamera=key;label.append(word('span',key),n);cameraFields.append(label);cameraInputs[key]=n;if(['aim','yaw','pitch'].includes(key))ui.help.add(label,()=>poseHelpLabels(language).aim,()=>t()[key]);n.addEventListener('change',()=>{if(type==='number'&&(n.value===''||!Number.isFinite(Number(n.value)))){refresh();return;}const next=clone(state),value=type==='checkbox'?n.checked:type==='number'?Number(n.value):n.value;if(['x','z','cameraHeight'].includes(key))next.camera.position[key==='cameraHeight'?'y':key]=value;else next.camera[key]=value;commit(next);});}
 const promptBox=el('details','pose-workspace-output');promptBox.append(word('summary','output'),output,button('rebuild',()=>commit({...clone(state),customDirections:null})),button('backup',()=>{try{const url=URL.createObjectURL(new Blob([JSON.stringify({...saved,state},null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download='Prompt-Studio-virtual-studio.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{status.textContent=t().failed;}}));document.body.append(promptBox);
 output.addEventListener('input',()=>commit({...clone(state),customDirections:output.value}));lang.addEventListener('change',()=>{language=lang.value;refresh();});
 function refresh(){for(const [n,key]of texts)n.textContent=t()[key];document.title=t().title+' — Prompt Studio';const directions=state.customDirections??studioPlanText(state);if(output.value!==directions)output.value=directions;output.setAttribute('aria-label',t().output);output.disabled=locked;const angles=state.camera.aim?studioAim(state.camera.position,state.subject):state.camera;for(const [key,n]of Object.entries(cameraInputs)){const value=['x','z','cameraHeight'].includes(key)?state.camera.position[key==='cameraHeight'?'y':key]:['yaw','pitch'].includes(key)?angles[key]:state.camera[key];if(n.type==='checkbox')n.checked=value;else n.value=String(typeof value==='number'?Math.round(value*1000)/1000:value);n.disabled=locked||state.camera.aim&&['yaw','pitch'].includes(key);n.setAttribute('aria-label',t()[key]);}ui?.refresh();if(locked)status.textContent=t().failed;}
 globalThis.addEventListener?.('storage',event=>{if(event.key===studioPlannerKey||event.key===null){syncExternal();}});refresh();return {getState:()=>clone(state),refresh,commit,ui,syncExternal,referenceReady};
}
